(()=>{
const baseRender=render,baseView=setView;
function tableRender(){const query=document.getElementById('query').value.toLowerCase(),owner=document.getElementById('owner').value;const rows=tasks.filter(t=>(owner==='all'||t.owner===owner)&&(t.title+t.desc+t.id).toLowerCase().includes(query));document.getElementById('count').textContent=rows.length+' 项工作';document.getElementById('board').innerHTML='<div class="activity-table-wrap"><table class="activity-table"><thead><tr><th>任务名称</th><th>任务说明</th><th>状态</th><th>执行者</th><th>操作</th></tr></thead><tbody>'+rows.map(t=>'<tr><td><button class="table-task-title" data-task="'+safe(t.id)+'">'+safe(t.title)+'</button></td><td class="table-description">'+safe(t.desc)+'</td><td><span class="table-state '+t.state+'"><i></i>'+safe(states.find(x=>x[0]===t.state)?.[1]||'运行中')+'</span></td><td><div class="table-owner"><span class="avatar"><img src="'+activityPortrait(t)+'" alt="角色IP头像" width="30" height="30" decoding="async"></span><span>'+safe(t.initiator|| (t.owner==='agent'?'智能体':'我'))+'</span></div></td><td><button class="table-analysis" data-analysis="'+safe(t.id)+'">✦ AI分析</button></td></tr>').join('')+'</tbody></table>'+(!rows.length?'<div class="table-empty">暂无匹配任务，请调整搜索或筛选条件。</div>':'')+'</div>';document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>details(b.dataset.task));document.querySelectorAll('[data-analysis]').forEach(b=>b.onclick=()=>{if(b.dataset.analysis==='ASSET-CONNECTION-ERROR'){details(b.dataset.analysis);return}if(b.dataset.analysis==='ERP-WMS-DAILY'){details(b.dataset.analysis);return}const t=tasks.find(t=>t.id===b.dataset.analysis);parent.postMessage({type:'erp-ai-analysis',task:{id:t.id,title:t.title,desc:t.desc,state:t.state}},location.origin)})}
render=function(){if(listView)tableRender();else baseRender()};setView=function(list){baseView(list);render()};if(listView)render();
})();
